import {
  Component,
  OnInit,
  ViewChild,
  HostListener,
  AfterViewInit,
  HostBinding,
  Inject,
  ElementRef,
} from '@angular/core';
import { Data, Router } from '@angular/router';
import {
  trigger,
  style,
  query,
  transition,
  stagger,
  animate,
} from '@angular/animations';
import { AnalyticsService } from 'src/app/services/analytics/analytics.service';
import { UntypedFormControl } from '@angular/forms';
import { LanguageService } from 'src/app/services/language/language.service';
import { ThemeService } from 'src/app/services/Theme/theme.service';
import { AuthService, User } from '@auth0/auth0-angular';
import { InteractionService } from 'src/app/services/interaction/interaction.service';
import { DataService } from 'src/app/services/data/data.service';

@Component({
  selector: 'app-header',
  templateUrl: './header.component.html',
  styleUrls: ['./header.component.scss'],

  animations: [
    trigger('animateMenu', [
      transition(':enter', [
        style({ opacity: 0, transform: 'translateY(-50%)' }),
        animate(
          '250ms cubic-bezier(0.35, 0, 0.25, 1)',
          style({ opacity: 1, transform: 'none' })
        ),
      ]),
    ]),
  ],
})
export class HeaderComponent implements OnInit {
  @HostBinding('class')
  currentTheme: 'light-theme' | 'dark-theme' = 'light-theme';

  isDarkMode: boolean = false;
  responsiveMenuVisible: Boolean = false;
  pageYPosition: number;
  languageFormControl: UntypedFormControl = new UntypedFormControl();
  cvName: string = '';
  isAuthenticated: boolean;
  user: any | null = null;
  sub: any;
  constructor(
    private router: Router,
    public analyticsService: AnalyticsService,
    public languageService: LanguageService,
    private themeService: ThemeService,
    public auth: AuthService,
    private dataService: DataService,
    public interactionService: InteractionService,
    private elementRef: ElementRef
  ) {
    this.interactionService.getMessage().subscribe((message) => {
      this.isAuthenticated = localStorage.getItem('isAuthenticated') === 'true';
      this.user = JSON.parse(message);
    });
  }

  ngOnInit(): void {
    this.sub = this.auth.user$.subscribe((user) => {
      this.user = user as User;
      if (!user || !user.sub) {
        return;
      }
      localStorage.setItem('userId', user.sub.split('|')[1]);
      this.interactionService.changeMessage(JSON.stringify(this.user, null, 2));
      if (user != null) {
        //check if userid already exists
        let isUserExists = false;
        this.dataService.getUserBasketList().subscribe((res: any) => {
          if(!res){
            return isUserExists = false;
          }
        const userId = user.sub.split('|')[1];
          if (res.length > 0) {
            for (let i = 0; i < res.length; i++) {
              if (res[i].name == userId) {
                return isUserExists = true;
              }
            }
          }
          if (!isUserExists) {
            this.dataService.addUserBasket(user).subscribe(
              (response: any) => {
                console.log('Success:', response);
              },
              (error: any) => {
                console.log('Error:', error);
              }
            );
          }
        });
      }
    });

    

    this.languageFormControl.valueChanges.subscribe((val) =>
      this.languageService.changeLanguage(val)
    );

    this.languageFormControl.setValue(this.languageService.language);
  }
  ngOnDestroy(): void {
    if (this.sub) {
      this.sub.unsubscribe();
    }
  }
  isUserExists(userData: User) {
    this.dataService.getUserBasketList().subscribe((res: any) => {
      if(!res){
        return false;
      }
    const userId = userData.sub.split('|')[1];
      if (res.length > 0) {
        for (let i = 0; i < res.length; i++) {
          if (res[i].name == userId) {
            return true;
          }
        }
      }
    });
    return false;
  }

  scroll(el) {
    if (document.getElementById(el)) {
      document.getElementById(el).scrollIntoView({ behavior: 'smooth' });
    } else {
      this.router
        .navigate(['/home'])
        .then(() =>
          document.getElementById(el).scrollIntoView({ behavior: 'smooth' })
        );
    }
    this.responsiveMenuVisible = false;
  }
  
  ngOnChanges() {
    this.onThemeChanged();
  }
  onThemeChanged() {
    this.isDarkMode = !this.isDarkMode;
    if (this.isDarkMode) {
      this.currentTheme = 'dark-theme';
    } else {
      this.currentTheme = 'light-theme';
    }
    this.themeService.switchTheme(this.currentTheme);
  }

  @HostListener('window:scroll', ['getScrollPosition($event)'])
  getScrollPosition(event) {
    this.pageYPosition = window.pageYOffset;
  }

  changeLanguage(language: string) {
    this.languageFormControl.setValue(language);
  }

  loginWithRedirect() {
    this.auth.loginWithRedirect();
  }
  ngAfterViewInit() {
    const asideElement = this.elementRef.nativeElement.querySelector('aside');
    if (asideElement) {
      console.log(asideElement.innerHTML);
    } else {
      console.log('Aside element not found');
    }
  }
  logout() {
    localStorage.clear();
    this.auth.logout({ logoutParams: { returnTo: window.location.origin } });
  }
}
