import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { User } from '@auth0/auth0-angular';
import { catchError, map, of } from 'rxjs';
import * as environment from 'src/environments/environment';

@Injectable({
  providedIn: 'root',
})
//It helps to upload data into getpantry.cloud https://getpantry.cloud/#
export class DataService {

  private httpOptions = {
    headers: new HttpHeaders({
      'Content-Type': 'application/json'
    })
  };

  constructor(private httpClient: HttpClient) {}
  
  getUserBasketList() {
    return this.httpClient.get(environment.environment.apiUrl)
    .pipe(
      map((res:any) => {
       const basketList = res.baskets;
       return basketList;
      }),
      catchError((error : any)=>{
        console.log(error);
        return of([]);
      })
    );
  }
  
  

  addUserBasket(userData: User) {
    const userId = userData.sub.split('|')[1];
    if (!userId) {
      throw new Error('Invalid user ID');
    }
    const transformedData = {
      userData: [
        {
          id: userId,
          email: userData.email,
          email_verified: userData.email_verified,
          given_name: userData.given_name,
          name: userData.name,
          nickname: userData.nickname,
          photo: userData.picture,
          sub: userData.sub,
          updated_at: userData.updated_at,
          pids: [],
          gender: "male",
        }
      ]
    };
    const url = `${environment.environment.apiUrl}/basket/${userId}`;
    
    return this.httpClient.post(url, transformedData);
  }

  
  getUserData() {
    let userID = localStorage.getItem('userId');
    return this.httpClient.get(environment.environment.apiUrl+'/basket/'+ userID);
  }

  postUserData(data: any) {
    let userID = localStorage.getItem('userId');
    return this.httpClient.post(environment.environment.apiUrl +'/basket/'+ userID, data);
  }
}
